import React, { useState, useEffect } from "react";
import styled from "styled-components";
import fetchBookDetails from "./fetchBookDetails";
import CardButton from "./CardButton";

const Overlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  display: ${(props) => (props.visible ? "flex" : "none")};
  justify-content: flex-end;
  z-index: 1000;
`;

const Panel = styled.div`
  background: #1f1f1f;
  width: 400px;
  max-width: 100%;
  height: 100%;
  padding: 20px;
  overflow-y: auto;
  position: relative;
  color: #fff;
`;

const CloseButton = styled.button`
  position: absolute;
  top: 15px;
  right: 15px;
  background: transparent;
  border: none;
  font-size: 1.5rem;
  color: #fff;
  cursor: pointer;
`;

const Title = styled.h2`
  margin: 0 0 10px;
`;

const Author = styled.p`
  margin: 0 0 15px;
  font-weight: 500;
`;

const Description = styled.p`
  font-size: 0.95rem;
  line-height: 1.4;
`;

const Cover = styled.img`
  width: 100%;
  border-radius: 12px;
  margin-bottom: 15px;
`;

const BookSidePanel = ({
    book,
    visible,
    onClose,
    inLibrary,
    onAdd,
    onRemove,
}) => {
    const [details, setDetails] = useState(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (!book) return;

        let isMounted = true;
        setLoading(true);

        const fetchDetails = async () => {
            try {
                const cached = JSON.parse(localStorage.getItem("bookCache") || "{}");
                if (cached[book.id]) {
                    if (isMounted) setDetails(cached[book.id]);
                } else {
                    const data = await fetchBookDetails(book);
                    if (isMounted) setDetails(data);
                    cached[book.id] = data;
                    localStorage.setItem("bookCache", JSON.stringify(cached));
                }
            } catch (err) {
                console.error("Error fetching book details:", err);
            } finally {
                if (isMounted) setLoading(false);
            }
        };

        fetchDetails();

        return () => {
            isMounted = false;
        };
    }, [book]);

    const handleAddRemove = () => {
        if (!details) return;
        if (inLibrary) {
            onRemove(details.title);
        } else {
            onAdd(details);
        }
    };

    if (!book) return null;

    return (
        <Overlay visible={visible} onClick={onClose}>
            <Panel onClick={(e) => e.stopPropagation()}>
                <CloseButton onClick={onClose}>&times;</CloseButton>

                {loading ? (
                    <p>Loading...</p>
                ) : details ? (
                    <>
                        <Cover src={details.cover || ""} alt={details.title} />
                        <Title>{details.title}</Title>
                        <Author>{details.authors?.join(", ")}</Author>
                        <Description>{details.description || "No description available."}</Description>

                        <CardButton
                            variant={inLibrary ? "remove" : "add"}
                            onClick={handleAddRemove}
                        >
                            {inLibrary ? "Remove from Library" : "Add to Library"}
                        </CardButton>
                    </>
                ) : (
                    <p>No details available</p>
                )}
            </Panel>
        </Overlay>
    );
};

export default BookSidePanel;
